//! Direct checks of stored spectral, sign-grid and finite-prefix witnesses.
//!
//! Endpoint phase, domination and Newton closure are still regenerated by the
//! suppliers after these checks; this module does not claim an independent
//! checker for those three obligations.

use super::*;

fn mismatch(message: &str) -> RecurrenceError {
    RecurrenceError::VerificationFailed(format!("effective-BKW stored witness: {message}"))
}
fn interval(bounds: &[String; 2]) -> Result<I, RecurrenceError> {
    let i = I::new(rational(&bounds[0])?, rational(&bounds[1])?);
    if i.lo > i.hi {
        return Err(mismatch("reversed enclosure"));
    }
    Ok(i)
}
fn root_count(p: &P, i: &I) -> usize {
    if i.lo == i.hi {
        return usize::from(p.evaluate(&i.lo).is_zero());
    }
    // Include both endpoints in the closed witness enclosure.
    let squarefree = crate::root_count::squarefree_part_primitive_bigint_coeffs(
        &vec_poly::clear_denominators(p.coeffs()),
    );
    crate::sturm::SturmChain::from_bigint_coeffs(&squarefree).count_roots_in(&i.lo, &i.hi)
        + usize::from(p.evaluate(&i.lo).is_zero())
        + usize::from(p.evaluate(&i.hi).is_zero())
}
fn sample(
    p: &B,
    f: &B,
    parameter: &str,
    bounds: &[String; 2],
    sign: i8,
    domain: &Domain,
) -> Result<(), RecurrenceError> {
    let t = rational(parameter)?;
    let mut point = I::point(t.clone());
    if domain.location(&P::new(vec![-&t, Q::one()]), &mut point, &q(1))? != 1 {
        return Err(mismatch("sample outside interval"));
    }
    let branch = interval(bounds)?;
    if root_count(&P::new(p.evaluate_variable(&t)), &branch) != 1
        || sign == 0
        || eval_b(f, &point, &branch).sign() != sign
    {
        return Err(mismatch("sample root enclosure or sign"));
    }
    Ok(())
}

fn signs(
    certificate: &EffectiveBkwCertificate,
    p: &B,
    domain: &Domain,
) -> Result<(), RecurrenceError> {
    for sign in &certificate.signs {
        let f = decode_b(&sign.polynomial)?;
        if f.is_zero() {
            if sign.sign != 0
                || !sign.resultant.is_empty()
                || !sign.off_branch_boxes.is_empty()
                || !sign.nonnegative_cell_samples.is_empty()
            {
                return Err(mismatch("zero sign identity"));
            }
            continue;
        }
        let independent_of_branch = f.index_degree() == Some(0);
        let branch = if independent_of_branch && sign.sample_branch == ["0", "0"] {
            variable()
        } else {
            p.clone()
        };
        let actual = decode(&sign.resultant)?;
        let derived = resultant(&branch, &f);
        // A univariate condition may have been emitted either directly or
        // after reduction in a higher-degree branch quotient. The resultant
        // is then f or f^degree; both have exactly the required critical set.
        if actual.is_zero()
            || (actual != derived && !(independent_of_branch && actual == resultant(p, &f)))
        {
            return Err(mismatch("resultant identity"));
        }
        let critical = domain.critical_roots(&critical_polynomial(&actual, domain))?;
        if sign.nonnegative_cell_samples.is_empty() {
            sample(
                &branch,
                &f,
                &sign.sample_parameter,
                &sign.sample_branch,
                sign.sign,
                domain,
            )?;
            if sign.off_branch_boxes.len() != critical.len() {
                return Err(mismatch("incomplete critical-root cover"));
            }
            for (root, stored) in critical.iter().zip(&sign.off_branch_boxes) {
                let t = interval(&stored.parameter)?;
                let r = interval(&stored.branch)?;
                let overlap = I::new(
                    t.lo.clone().max(root.lo.clone()),
                    t.hi.clone().min(root.hi.clone()),
                );
                if overlap.lo > overlap.hi || root_count(&actual, &overlap) != 1 {
                    return Err(mismatch("critical-root enclosure"));
                }
                let walls = [
                    eval_b(&branch, &t, &I::point(r.lo.clone())).sign(),
                    eval_b(&branch, &t, &I::point(r.hi.clone())).sign(),
                ];
                if walls != stored.wall_signs
                    || walls[0] * walls[1] != -1
                    || stored.condition_sign != sign.sign
                    || eval_b(&f, &t, &r).sign() != sign.sign
                {
                    return Err(mismatch("off-branch wall or condition sign"));
                }
            }
        } else {
            if sign.sign != 1
                || !sign.off_branch_boxes.is_empty()
                || sign.nonnegative_cell_samples.len() != critical.len() + 1
            {
                return Err(mismatch("nonnegative cell cover"));
            }
            for (i, cell) in sign.nonnegative_cell_samples.iter().enumerate() {
                let t = rational(&cell.parameter)?;
                // Compare exactly with each algebraic critical root, allowing
                // different valid rational samples and isolating enclosures.
                let half = Domain {
                    wire: domain.wire.clone(),
                    lower: None,
                    upper: Some(End {
                        polynomial: P::new(vec![-&t, Q::one()]),
                        bounds: I::point(t.clone()),
                    }),
                    sample: t.clone(),
                };
                let mut before = 0;
                for root in &critical {
                    let mut root = root.clone();
                    match half.location(&actual, &mut root, &q(1))? {
                        1 => before += 1,
                        0 => return Err(mismatch("cell sample is a critical root")),
                        _ => (),
                    }
                }
                if before != i || cell.sign != 1 {
                    return Err(mismatch("cell sample order or sign"));
                }
                sample(
                    &branch,
                    &f,
                    &cell.parameter,
                    &cell.branch,
                    cell.sign,
                    domain,
                )?;
            }
        }
    }
    Ok(())
}

pub(super) fn witnesses(report: &EffectiveBkwReport) -> Result<(), RecurrenceError> {
    let Some(certificate) = &report.certificate else {
        return Ok(());
    };
    if certificate.domination_cutoff.is_none() {
        return Err(mismatch(
            "legacy certificate lacks domination_cutoff; regenerate it",
        ));
    }
    let request = match certificate.coordinate_transport {
        EffectiveBkwCoordinateTransport::Identity => report.request.clone(),
        EffectiveBkwCoordinateTransport::ParameterReflectionWithAlternatingRows => {
            reflect_request(&report.request)?
        }
    };
    let numerator = decode_b(&request.generating_function.numerator)?;
    let denominator = decode_b(&request.generating_function.denominator)?;
    let d: Vec<_> = denominator
        .rows()
        .iter()
        .map(|r| P::new(r.clone()))
        .collect();
    if d.len() < 3 || d[0] != P::one() {
        return Err(mismatch("denominator shape"));
    }
    let expected = B::new(d.iter().rev().map(|r| r.coeffs().to_vec()).collect());
    if decode_b(&certificate.characteristic)? != expected {
        return Err(mismatch("characteristic identity"));
    }
    let p = decode_b(&certificate.branch_equation)?;
    if p.index_degree().is_none_or(|d| d == 0) || p.rows().last() != Some(&vec![Q::one()]) {
        return Err(mismatch("branch equation must be monic and nonconstant"));
    }
    let domain = Domain::select(&P::one(), d.len() - 1, &Some(certificate.interval.clone()))
        .map_err(RecurrenceError::from)?;
    let decode_r = |r: &EffectiveBkwBranchRational| -> Result<R, RecurrenceError> {
        let denominator = decode_b(&r.denominator)?;
        if denominator.is_zero() || rem(&denominator, &p).is_zero() {
            return Err(mismatch("zero spectral denominator"));
        }
        Ok(R::new(decode_b(&r.numerator)?, denominator).modulo(&p))
    };
    let data = &certificate.expansion_data;
    let a = decode_r(&data.pair_real_part)?;
    let b = decode_r(&data.pair_norm_squared)?;
    let h = data
        .cofactor
        .iter()
        .map(decode_r)
        .collect::<Result<Vec<_>, _>>()?;
    if h.len() + 2 != d.len() {
        return Err(mismatch("cofactor degree"));
    }
    let pair = [R::of(c(1)), a.scale(&q(-2)), b];
    let mut product = vec![R::of(c(0)); d.len()];
    for (i, u) in pair.iter().enumerate() {
        for (j, v) in h.iter().enumerate() {
            product[i + j] = product[i + j].add(&u.mul(v));
        }
    }
    for (actual, expected) in product.iter().zip(&d) {
        if !rem(&actual.sub(&R::of(t(expected))).n, &p).is_zero() {
            return Err(mismatch("pair/cofactor identity"));
        }
    }
    signs(certificate, &p, &domain)?;
    if certificate.finite_rows.len() != certificate.cutoff {
        return Err(mismatch("finite-prefix length"));
    }
    let mut rows: Vec<P> = Vec::new();
    for (n, stored) in certificate.finite_rows.iter().enumerate() {
        let mut row = P::new(numerator.rows().get(n).cloned().unwrap_or_default());
        for j in 1..d.len().min(n + 1) {
            row = row - d[j].clone() * rows[n - j].clone();
        }
        let degree = row.degree().ok_or_else(|| mismatch("zero finite row"))?;
        let roots = crate::root_count::count_real_roots_prs_bigint_coeffs(
            &vec_poly::clear_denominators(row.coeffs()),
        );
        if stored.index
            != request
                .generating_function
                .first_index
                .checked_add(n)
                .ok_or_else(|| mismatch("row index overflow"))?
            || decode(&stored.coefficients)? != row
            || stored.degree != degree
            || stored.distinct_real_roots != roots
            || roots != degree
        {
            return Err(mismatch("finite row identity, degree or root count"));
        }
        rows.push(row);
    }
    Ok(())
}
